//! TLS: the round trip with a certificate generated by the test, and the refusals.
//!
//! The certificate and key are made fresh in each test and written under the target
//! directory; nothing here is a real secret and nothing is checked in.

use std::sync::Arc;

use rustls::ClientConfig;
use rustls::crypto::ring::default_provider;
use rustls::pki_types::pem::PemObject;
use rustls::pki_types::{CertificateDer, ServerName};
use tokio::io::{AsyncReadExt, AsyncWriteExt};
use tokio_rustls::TlsConnector;

use crate::support::{
    Harness, Scratch, TOKEN, args_with, config, exchange, lease_body, replace, request,
};
use js_lease_server::{SharedClock, channel_ticker, start};

/// A certificate for 127.0.0.1 and its key, as PEM text.
fn test_identity() -> (String, String) {
    let names = vec!["127.0.0.1".to_string(), "localhost".to_string()];
    let made = rcgen::generate_simple_self_signed(names).unwrap();
    (made.cert.pem(), made.signing_key.serialize_pem())
}

/// A client that trusts exactly `cert_pem`.
fn connector(cert_pem: &str) -> TlsConnector {
    let mut roots = rustls::RootCertStore::empty();
    roots
        .add(CertificateDer::from_pem_slice(cert_pem.as_bytes()).unwrap())
        .unwrap();
    let config = ClientConfig::builder_with_provider(Arc::new(default_provider()))
        .with_safe_default_protocol_versions()
        .unwrap()
        .with_root_certificates(roots)
        .with_no_client_auth();
    TlsConnector::from(Arc::new(config))
}

async fn tls_request(
    addr: std::net::SocketAddr,
    connector: &TlsConnector,
    method: &str,
    path: &str,
    token: Option<&str>,
    body: Option<&[u8]>,
) -> crate::support::Reply {
    let tcp = tokio::net::TcpStream::connect(addr).await.unwrap();
    let name = ServerName::IpAddress(addr.ip().into());
    let stream = connector.connect(name, tcp).await.unwrap();
    exchange(stream, method, path, token, body).await
}

/// A server with TLS flags from freshly generated test files.
async fn tls_server(name: &str, listen: &str) -> (Harness, String) {
    let scratch = Scratch::new(name);
    let (cert, key) = test_identity();
    let cert_file = scratch.write("test-only-cert.pem", &cert, 0o644);
    let key_file = scratch.write("test-only-key.pem", &key, 0o600);
    let args = args_with(
        &scratch,
        &[
            "--tls-cert",
            cert_file.to_str().unwrap(),
            "--tls-key",
            key_file.to_str().unwrap(),
        ],
    );
    let args = replace(args, "--listen", listen);
    (Harness::with(scratch, args, None).await, cert)
}

/// Asserts that a client trusting the certificate gets answers over TLS (health,
/// authentication, a lease), that a client speaking plain HTTP or garbage to the port
/// is dropped without an answer, and that the server serves on afterwards.
#[tokio::test]
async fn tls_round_trip() {
    let (h, cert) = tls_server("tls_round_trip", "127.0.0.1:0").await;
    let connector = connector(&cert);
    let addr = h.addr();

    let health = tls_request(addr, &connector, "GET", "/healthz", None, None).await;
    assert_eq!((health.status, health.body.as_str()), (200, "ok"));
    let denied = tls_request(addr, &connector, "GET", "/v1/leases", None, None).await;
    assert_eq!(denied.status, 401);
    let body = lease_body().to_string().into_bytes();
    let made = tls_request(
        addr,
        &connector,
        "POST",
        "/v1/leases",
        Some(TOKEN),
        Some(&body),
    )
    .await;
    assert_eq!(made.status, 201, "{}", made.body);

    let plain = request(addr, "GET", "/healthz", None, None).await;
    assert_eq!(plain.status, 0);
    let mut junk = tokio::net::TcpStream::connect(addr).await.unwrap();
    junk.write_all(&[0x16, 0x03, 0x01, 0xff, 0xff, 0, 0, 0])
        .await
        .unwrap();
    let mut seen = Vec::new();
    let _ = junk.read_to_end(&mut seen).await;
    assert!(!seen.starts_with(b"HTTP/"));

    let again = tls_request(addr, &connector, "GET", "/v1/leases", Some(TOKEN), None).await;
    assert_eq!(again.status, 200);
}

/// Asserts that a client that does not trust the certificate cannot complete a
/// handshake.
#[tokio::test]
async fn an_untrusted_client_is_refused() {
    let (h, _) = tls_server("tls_untrusted", "127.0.0.1:0").await;
    let (other, _) = test_identity();
    let connector = connector(&other);
    let tcp = tokio::net::TcpStream::connect(h.addr()).await.unwrap();
    let name = ServerName::IpAddress(h.addr().ip().into());
    assert!(connector.connect(name, tcp).await.is_err());
}

/// Asserts that a listen address off the loopback starts once both TLS flags are given.
#[tokio::test]
async fn a_wildcard_address_serves_over_tls() {
    let (h, cert) = tls_server("tls_wildcard", "0.0.0.0:0").await;
    let loopback = std::net::SocketAddr::from(([127, 0, 0, 1], h.addr().port()));
    let reply = tls_request(loopback, &connector(&cert), "GET", "/healthz", None, None).await;
    assert_eq!(reply.status, 200);
}

/// Asserts that unusable TLS files are refused naming the flag of the file at fault: a
/// missing or empty or unreadable certificate, a missing or unreadable key, and a key
/// that does not belong to the certificate.
#[tokio::test]
async fn bad_tls_files_are_refused() {
    let scratch = Scratch::new("tls_bad");
    let (cert, key) = test_identity();
    let (_, other_key) = test_identity();
    let good_cert = scratch.write("test-only-cert.pem", &cert, 0o644);
    let good_key = scratch.write("test-only-key.pem", &key, 0o600);
    let wrong_key = scratch.write("test-only-other-key.pem", &other_key, 0o600);
    let empty = scratch.write("empty.pem", "", 0o644);
    let junk = scratch.write("junk.pem", "not pem at all", 0o644);
    let absent = scratch.path("absent.pem");

    let cases = [
        (&absent, &good_key, "--tls-cert"),
        (&empty, &good_key, "--tls-cert"),
        (&junk, &good_key, "--tls-cert"),
        (&good_cert, &absent, "--tls-key"),
        (&good_cert, &junk, "--tls-key"),
        (&good_cert, &wrong_key, "--tls-key"),
    ];
    for (cert, key, flag) in cases {
        let args = args_with(
            &scratch,
            &[
                "--tls-cert",
                cert.to_str().unwrap(),
                "--tls-key",
                key.to_str().unwrap(),
            ],
        );
        let (_, ticker) = channel_ticker();
        let clock = SharedClock::new(js_lease::ManualClock::default());
        let err = start(config(args).unwrap(), clock, ticker)
            .await
            .err()
            .unwrap();
        assert_eq!(err.flag(), flag, "{cert:?} {key:?}: {err}");
    }
}
